-- Add the second supplied set of Lily facts (cards 101–200). The source text
-- uses the preferred neutral wording “литературных рабов” for fact 113.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (101, $$Прототипом Шерлока Холмса был профессор медицины Джозеф Белл. Он мог по мелким деталям внешности определить профессию, происхождение и диагноз пациента до того, как тот открывал рот.$$),
  (102, $$Алиса Лидделл — реальная девочка, для которой Льюис Кэрролл сочинил свою сказку. В отличие от книжной Алисы, настоящая была брюнеткой с короткой челкой.$$),
  (103, $$Джеймс Бонд получил свое имя в честь американского орнитолога (эксперта по птицам), автора справочника «Птицы Вест-Индии». Ян Флеминг искал «самое простое и скучное имя».$$),
  (104, $$Прототипом Питера Пэна стал Майкл Ллевелин Дэвис, один из мальчиков, которых опекал писатель Джеймс Барри. Майкл трагически утонул в возрасте 20 лет.$$),
  (105, $$Длинный Джон Сильвер из «Острова сокровищ» списан с близкого друга Стивенсона — писателя Уильяма Хенли. Тот потерял ногу из-за туберкулеза костей, но оставался невероятно энергичным и громким человеком.$$),
  (106, $$Граф Дракула в черновиках Брэма Стокера изначально именовался просто граф Вампир. Имя «Дракула» автор нашел в исторической книге о Валахии и перевел его для себя как «дьявол».$$),
  (107, $$Винни-Пух получил первую часть имени от медведицы Виннипег, жившей в Лондонском зоопарке, а вторую часть («Пух») — от лебедя, которого Кристофер Робин встретил на пруду.$$),
  (108, $$Прототипом профессора Мориарти стал Адам Ворт — реальный криминальный гений XIX века, которого Скотленд-Ярд называл «Наполеоном преступного мира».$$),
  (109, $$Остап Бендер имел реального прототипа — Осипа Шора, одесского инспектора уголовного розыска, который обладал потрясающим чувством юмора и в юности зарабатывал на жизнь мелким мошенничеством.$$),
  (110, $$Гулливер в романе Джонатана Свифта описывает два спутника Марса за 150 лет до того, как астрономы реально открыли Фобос и Деймос.$$),
  (111, $$Шарлотта, Эмили и Энн Бронте изначально публиковали свои романы («Джейн Эйр», «Грозовой перевал») под мужскими псевдонимами Каррер, Эллис и Эктон Белл, так как викторианское общество предвзято относилось к женщинам-авторам.$$),
  (112, $$Марк Твен был запатентованным изобретателем. Среди его изобретений — самоклеящийся альбом для вырезок и улучшенный ремешок для жилетов (прообраз застежки бюстгальтера).$$),
  (113, $$Александр Дюма-отец нанимал целую команду «литературных рабов» (самым известным был Огюст Маке). Они писали костяк сюжета и историческую справку, а Дюма раскрашивал текст своим живым стилем.$$),
  (114, $$Уильям Фолкнер написал свой шедевр «Когда я умирала» за шесть недель, работая ночным сторожем на электростанции, используя в качестве стола перевернутую тачку.$$),
  (115, $$Джон Стейнбек написал «Гроздья гнева» тремястами деревянными карандашами. Он стачивал их с такой скоростью, что помощник едва успевал их менять.$$),
  (116, $$Джек Керуак напечатал свой культовый роман «В дороге» на одном единственном 36-метровом рулоне факсовой бумаги за три недели. Он склеил листы скотчем, чтобы не отвлекаться на смену бумаги в машинке.$$),
  (117, $$Дюма-сын (автор «Дамы с камелиями») коллекционировал женские панталоны.$$),
  (118, $$Вольтер так сильно любил кофе, что выпивал около 40 чашек в день. Его личный врач предупреждал, что этот напиток его убьет, на что Вольтер ответил: «Кофе — медленный яд, раз я пью его уже 80 лет».$$),
  (119, $$Ганс Христиан Андерсен панически боялся сгореть заживо, поэтому во все путешествия брал с собой толстую веревку, чтобы в случае пожара спуститься из окна отеля.$$),
  (120, $$Трумен Капоте никогда не начинал и не заканчивал книги по пятницам, а также не останавливался в гостиничных номерах, где в номере присутствовала цифра 13.$$),
  (121, $$«Лолита» Набокова была запрещена в Великобритании, Франции и Аргентине сразу после публикации как порнография, что лишь подхлестнуло ее мировые продажи.$$),
  (122, $$«Улисс» Джеймса Джойса сжигал американские и английские почтовые службы. Официально книга была запрещена в США до 1933 года из-за «непристойности».$$),
  (123, $$«Манифест Коммунистической партии» Маркса и Энгельса изначально был напечатан тиражом всего в несколько сотен экземпляров в крошечной лондонской типографии.$$),
  (124, $$Библия Гутенберга (первая крупная книга, отпечатанная подвижными литерами) стоила при выпуске столько, сколько обычный клерк зарабатывал за три года.$$),
  (125, $$«Алиса в Стране чудес» была официально запрещена в китайской провинции Хунань в 1931 году, потому что «животные не должны говорить человеческим языком и стоять на одном уровне с людьми».$$),
  (126, $$«Американский психопат» Брета Истона Эллиса до сих пор продается в Австралии только в специальной термоусадочной пленке, и книгу запрещено продавать лицам моложе 18 лет.$$),
  (127, $$«1984» Джорджа Оруэлла умудрилась побывать под запретом как в СССР (за критику тоталитаризма), так и в некоторых округах США (за «прокоммунистические» и «антихристианские» идеи).$$),
  (128, $$«Дневник Анны Франк» в Ливане запрещен к публикации и распространению из-за того, что книга «изображает евреев в слишком позитивном свете».$$),
  (129, $$«Доктор Живаго» Бориса Пастернака тайно печатался и распространялся силами ЦРУ США как инструмент антисоветской пропаганды.$$),
  (130, $$«Тысяча и одна ночь» в ее классическом арабском варианте долгое время считалась на Востоке «низкой литературой для базарной черни» и не признавалась серьезными учеными.$$),
  (131, $$Самая толстая печатная книга в мире имеет толщину 4,96 метра и содержит 40 341 страницу. Это сборник всех отзывов о мини-автомобиле «Scion», собранных в интернете.$$),
  (132, $$Агата Кристи — самый переводимый индивидуальный автор в истории человечества (ее книги переведены на 103 языка).$$),
  (133, $$Самый крупный гонорар за слово получил бывший президент США Билл Клинтон за свои мемуары «Моя жизнь» — ему платили около 50 долларов за каждое написанное слово.$$),
  (134, $$Первый книжный магазин в современном понимании открылся в Лиссабоне (Португалия) в 1732 году — магазин «Livraria Bertrand» работает по тому же адресу до сих пор.$$),
  (135, $$Слово «ППШ» или «автомат» в книгах о войне встречается реже, чем слово «винтовка», даже в описаниях сражений 1944 года.$$),
  (136, $$Самый старый сохранившийся роман в мире — японская «Повесть о Гэндзи» (XI век), написанная дворянкой Мурасаки Сикибу.$$),
  (137, $$Каждые 30 секунд в мире покупают один экземпляр романа «Алхимик» Пауло Коэльо.$$),
  (138, $$Самая посещаемая библиотека в мире — Нью-Йоркская публичная библиотека. Ежегодно через ее залы проходит более 16 миллионов человек.$$),
  (139, $$«Гарри Поттер и Дары Смерти» установил мировой рекорд скорости продаж: в первые сутки после выхода книги было продано 11 миллионов экземпляров.$$),
  (140, $$Самым старым лауреатом Нобелевской премии по литературе стала Дорис Лессинг — она получила награду в возрасте 88 лет.$$),
  (141, $$Роман «Гэдсби» (Gadsby) Эрнеста Винсента Райта, написанный в 1939 году, состоит из 50 000 слов, и в нем ни разу не используется буква «E» — самая частая буква английского языка. Этот жанр называется липограмма.$$),
  (142, $$В романе «Мастер и Маргарита» Воланд ни разу не называет Христа по имени «Иисус», используя только арамейскую форму «Иешуа».$$),
  (143, $$Палиндром — это текст, который читается одинаково в обоих направлениях. Самый длинный роман-палиндром «Dr Awkward & Olson in Oslo» содержит 31 954 слова.$$),
  (144, $$Слово «тарзанка» появилось в русском языке исключительно благодаря популярности книг Эдгара Берроуза о Тарзане.$$),
  (145, $$Джонатан Свифт в «Путешествиях Гулливера» придумал слово Yahoo (еху) для описания грубых, скотоподобных существ. Спустя 250 лет создатели поисковика Yahoo! использовали это слово для названия компании.$$),
  (146, $$Льюис Кэрролл изобрел «словесные звенья» (дуплеты) — игру, где нужно превратить одно слово в другое, меняя по одной букве ( например, МУХА - МУРА - ТУРА - ТАРА - СЛОН).$$),
  (147, $$Слово «саботаж» популяризировал французский писатель Эмиль Пуже в своих анархистских брошюрах.$$),
  (148, $$Эдгар Аллан По написал стихотворение «Ворон» с использованием сложнейшего математического расчета ритма и звуков, чтобы оно вызывало у читателя подсознательное чувство меланхолии.$$),
  (149, $$Антуан де Сент-Экзюпери сам нарисовал все иллюстрации к «Маленькому принцу». Они являются неотъемлемой частью текста, так как герои постоянно ссылаются на них.$$),
  (150, $$Слово «кварк» физик Мюррей Гелл-Манн взял из фантастического романа Джеймса Джойса «Поминки по Финнегану» («Три кварка для мистера Марка!»).$$),
  (151, $$Иван Тургенев был невероятным педантом и чистюлей. Он не мог начать писать, если на его столе лежал хотя бы один предмет не на своем месте, и менял галстук по три раза в день.$$),
  (152, $$Николай Некрасов был страстным и очень успешным игроком в карты. На выигранные деньги он содержал и развивал свой знаменитый журнал «Современник».$$),
  (153, $$Михаил Лермонтов был не только поэтом, но и прекрасным художником — он оставил после себя более десятка масляных картин и массу акварелей, в основном с видами Кавказа.$$),
  (154, $$Владимир Маяковский страдал гермофобией (боязнью микробов) после того, как его отец умер от заражения крови, уколовшись обычной иголкой. Поэт всегда носил с собой мыло и спирт.$$),
  (155, $$Александр Грибоедов был профессиональным дипломатом и знал 9 языков (включая персидский, арабский и санскрит).$$),
  (156, $$Лев Толстой в старости полностью отказался от авторских прав на свои произведения, что вызвало грандиозный скандал и раскол в его семье.$$),
  (157, $$Сергей Есенин писал стихи на манжетах своих рубашек, когда под рукой не было бумаги.$$),
  (158, $$Николай Гоголь панически боялся быть похороненным заживо (в состоянии летаргического сна) и завещал хоронить себя только тогда, когда появятся явные признаки разложения.$$),
  (159, $$Афанасий Фет и Иван Тургенев однажды поссорились так сильно, что Фет вызвал Тургенева на дуэль. К счастью, друзья смогли их помирить.$$),
  (160, $$Корней Чуковский (Николай Корнейчуков) изначально был серьезным литературным критиком и переводчиком Уитмена и Оскара Уайльда, а детские сказки начал писать случайно, чтобы развлечь заболевшего сына.$$),
  (161, $$Стивен Кинг продает права на экранизацию своих коротких рассказов начинающим режиссерам и студентам всего за 1 доллар в рамках программы «Dollar Baby».$$),
  (162, $$Айзек Азимов в 1964 году предсказал появление плоских телевизоров, 3D-экранов, беспроводной связи и автономных марсоходов к 2014 году.$$),
  (163, $$Рэй Брэдбери в «451 градус по Фаренгейту» описал портативные радиоприемники («ракушки»), которые вставляются в уши — точное описание современных беспроводных наушников.$$),
  (164, $$Герберт Уэллс в романе «Освобожденный мир» (1914 год) предсказал появление и применение атомной бомбы, причем использовал именно это словосочетание.$$),
  (165, $$Джон Толкин считал «Властелина колец» не выдумкой, а попыткой реконструировать мифологию древней Англии, которая, по его мнению, была утеряна.$$),
  (166, $$Термин «робототехника» и три закона роботехники были сформулированы Айзеком Азимовым в рассказе «Хоровод» (1942).$$),
  (167, $$Фрэнк Герберт написал роман «Дюна» после того, как его наняли написать статью о песчаных дюнах в штате Орегон. Статью он так и не закончил, но собрал материал на культовую сагу.$$),
  (168, $$Артур Кларк в 1945 году детально описал идею использования геостационарных спутников для создания всемирной системы связи. Сегодня эта орбита называется «орбитой Кларка».$$),
  (169, $$Филип Дик (автор «Бегущего по лезвию») утверждал, что многие его сюжеты были продиктованы ему «розовым лучом света», транслировавшим информацию прямо в его мозг.$$),
  (170, $$Джордж Мартин признавался, что прототипом Стены в «Песне Льда и Пламени» стал реальный Вал Адриана в Шотландии, который защищал Римскую империю от набегов пиктов.$$),
  (171, $$Первые мягкие обложки (pocketbooks) появились во время Второй мировой войны. Их выпускали для солдат, чтобы книги легко помещались в карман военной формы.$$),
  (172, $$Книги-аллигаторы — это старинный термин для книг, обтянутых грубой шагреневой кожей, напоминающей кожу рептилий.$$),
  (173, $$Шрифт Times New Roman был разработан в 1931 году по заказу британской газеты The Times после того, как типографы раскритиковали старый шрифт газеты за плохую читаемость.$$),
  (174, $$Суперобложка (съемная бумажная обложка) изначально создавалась в XIX веке исключительно для защиты дорогого тканевого переплета во время транспортировки, и ее предполагалось выбрасывать после покупки.$$),
  (175, $$В древней Японии существовали «книги на свитках», которые разворачивались горизонтально. Читать их нужно было строго справа налево.$$),
  (176, $$Обрезание страниц — вплоть до начала XX века многие книги продавались с неразрезанными страницами. Читатель должен был сам разрезать листы специальным костяным ножом по мере чтения.$$),
  (177, $$Фронтиспис — рисунок, расположенный на одном развороте с титульным листом. В старинных книгах там чаще всего размещали портрет автора или покровителя, оплатившего печать.$$),
  (178, $$Экслибрис — бумажный ярлык или штамп владельца книги, который наклеивался на форзац. В старину на экслибрисах часто рисовали фамильные гербы или писали проклятия для тех, кто украдет книгу.$$),
  (179, $$Инкунабулы — это книги, напечатанные в Европе от начала книгопечатания до 1 января 1501 года. Их сохранилось очень мало, и каждая стоит целое состояние.$$),
  (180, $$Макулатурный переплет — средневековые переплетчики часто использовали старые, «ненужные» пергаментные рукописи для укрепления обложек новых книг. Сегодня ученые находят под обложками уникальные утерянные тексты.$$),
  (181, $$Дж. К. Роулинг написала первые наброски «Гарри Поттера» на обычных бумажных салфетках в шотландских кафе, так как у нее не было денег на нормальную бумагу.$$),
  (182, $$Хэлед Хоссейни (автор «Бегущего за ветром») по профессии врач-терапевт и долгое время совмещал ночные смены в госпитале с написанием своих драматических романов.$$),
  (183, $$Стивен Кинг выбрасывал рукопись своего первого романа «Кэрри» в мусорное ведро, посчитав ее провальной. Его жена Табита достала листы из мусора и заставила мужа дописать книгу.$$),
  (184, $$Ю Несбё (автор детективов о Харри Холе) в молодости был профессиональным футболистом, но из-за травмы колена в 19 лет был вынужден уйти из спорта.$$),
  (185, $$Дэн Браун использует метод «инверсионной терапии» для борьбы с творческим кризисом — он висит вниз головой на специальных гравитационных ботинках.$$),
  (186, $$Нил Гейман пишет все свои первые черновики исключительно перьевой ручкой в больших блокнотах, и только потом перебирает текст на компьютере.$$),
  (187, $$Джордж Мартин нанимает специальных фанатов-экспертов, чтобы они проверяли его новые главы на предмет логических ошибок в генеалогических древах его сотен персонажей.$$),
  (188, $$Чак Паланик написал «Бойцовский клуб» как короткий рассказ на 7 страниц после того, как его избили в кемпинге за то, что он попросил соседей сделать музыку тише.$$),
  (189, $$Стефани Майер до публикации «Сумерек» не написала ни одного художественного текста и занималась исключительно воспитанием троих детей.$$),
  (190, $$Патрик Зюскинд ведет абсолютно затворнический образ жизни. Он не дает интервью, не появляется на публике и отказался от нескольких крупных литературных премий.$$),
  (191, $$Фраза «Ад — это другие» Жан-Поля Сартра (из пьесы «За закрытыми дверями») часто понимается неверно. Писатель имел в виду не то, что люди плохи, а то, насколько мы зависимы от чужого мнения о нас.$$),
  (192, $$Выражение «Все смешалось в доме Облонских» Льва Толстого («Анна Каренина») стало классическим описанием полного хаоса и неразберихи.$$),
  (193, $$Фраза «Мы в ответе за тех, кого приручили» Экзюпери в оригинальном французском контексте касалась не только домашних животных, но и ответственности между близкими людьми в целом.$$),
  (194, $$Выражение «Двадцать два несчастья» пришло в русский язык из пьесы Антона Чехова «Вишневый сад» — так называли конторщика Епиходова.$$),
  (195, $$Слово «Робот» происходит от чешского слова robota, что означает «каторжный труд» или «барщина».$$),
  (196, $$Строчка «Умом Россию не понять» Федора Тютчева была написана им на клочке бумаги во время поездки в поезде.$$),
  (197, $$Фраза «О спорт, ты — мир!» была написана Пьером де Кубертеном для конкурса искусств на Олимпийских играх 1912 года под литературным псевдонимом.$$),
  (198, $$Слово «Утопия» содержит в себе игру слов на древнегреческом: оно может переводиться и как u-topos (место, которого нет), и как eu-topos (благословенное, хорошее место).$$),
  (199, $$Фраза «Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему» — одна из самых цитируемых первых строчек в мировой литературе («Анна Каренина»).$$),
  (200, $$Выражение «Рыцарь печального образа» прочно закрепилось за Дон Кихотом благодаря его верному оруженосцу Санчо Пансе.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  CASE WHEN ordinal BETWEEN 141 AND 150 THEN 'PHILOLOGY' ELSE 'LITERATURE' END,
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;
